"""Tool for batch processing multiple replay picture URLs from VST."""

import json
import logging

from nat.builder.builder import Builder
from nat.builder.framework_enum import LLMFrameworkEnum
from nat.builder.function_info import FunctionInfo
from nat.cli.register_workflow import register_function
from nat.data_models.component_ref import FunctionRef
from nat.data_models.function import FunctionBaseConfig
from pydantic import BaseModel
from pydantic import Field

logger = logging.getLogger(__name__)


class StreamTimePair(BaseModel):
    """Represents a stream_id and start_time pair."""

    stream_id: str = Field(..., description="UUID of the camera stream")
    start_time: str = Field(..., description="Start time in ISO 8601 UTC format (e.g., '2025-09-26T17:12:43Z')")


class VSTBatchReplayPicturesConfig(FunctionBaseConfig, name="vst_batch_replay_pictures"):
    """Configuration for the VST Batch Replay Pictures tool."""

    get_replay_picture_url_tool: FunctionRef = Field(
        ..., description="Reference to the vst_get_replay_picture_url tool"
    )
    default_expiry_minutes: str = Field(
        default="10080",  # 7 days
        description="Default expiration time in minutes for URLs",
    )


class VSTBatchReplayPicturesInput(BaseModel):
    """Input for batch processing replay pictures."""

    stream_time_pairs: list[StreamTimePair] = Field(
        ..., description="List of stream_id and start_time pairs to process", min_length=1
    )
    expiry_minutes: str | None = Field(
        default=None, description="Optional expiration time in minutes for all URLs (overrides default)"
    )
    overlay: str | None = Field(
        default=None, description="Optional JSON string for overlay configuration to apply to all images"
    )

    model_config = {"extra": "forbid"}


class VSTBatchReplayPicturesOutput(BaseModel):
    """Output containing list of image URLs."""

    image_urls: list[str] = Field(..., description="List of temporary URLs for accessing the replay pictures")
    processed_count: int = Field(..., description="Number of stream/time pairs successfully processed")
    errors: list[dict[str, str]] = Field(
        default_factory=list, description="List of any errors encountered during processing"
    )


@register_function(config_type=VSTBatchReplayPicturesConfig, framework_wrappers=[LLMFrameworkEnum.LANGCHAIN])
async def vst_batch_replay_pictures(config: VSTBatchReplayPicturesConfig, builder: Builder):
    """
    Batch process multiple replay picture requests from VST.

    This tool takes a list of stream_id/start_time pairs and calls the
    vst_get_replay_picture_url tool for each pair, collecting all the
    resulting image URLs into a single list.

    Example input:
    ```json
    {
        "stream_time_pairs": [
            {"stream_id": "Building_K_Cam1", "start_time": "2025-09-26T17:12:43Z"},
            {"stream_id": "Building_K_Cam2", "start_time": "2025-09-26T17:15:00Z"}
        ],
        "expiry_minutes": "1440"
    }
    ```

    Returns a list of image URLs that can be used to access the replay pictures.
    """
    # Get the replay picture URL tool
    get_replay_picture_url_tool = await builder.get_tool(
        config.get_replay_picture_url_tool, wrapper_type=LLMFrameworkEnum.LANGCHAIN
    )

    async def _vst_batch_replay_pictures(input_data: VSTBatchReplayPicturesInput) -> VSTBatchReplayPicturesOutput:
        """Process multiple stream/time pairs and return list of image URLs."""
        image_urls = []
        errors = []
        processed_count = 0

        # Determine expiry to use
        expiry_minutes = input_data.expiry_minutes or config.default_expiry_minutes

        # Process each stream/time pair
        for idx, pair in enumerate(input_data.stream_time_pairs):
            try:
                logger.info(
                    f"Processing pair {idx + 1}/{len(input_data.stream_time_pairs)}: "
                    f"stream_id={pair.stream_id}, start_time={pair.start_time}"
                )

                # Prepare the input for vst_get_replay_picture_url
                replay_input = {
                    "stream_id": pair.stream_id,
                    "start_time": pair.start_time,
                    "expiry_minutes": expiry_minutes,
                }

                # Add overlay if specified
                if input_data.overlay:
                    replay_input["overlay"] = input_data.overlay

                # Call the get_replay_picture_url tool
                result_str = await get_replay_picture_url_tool.ainvoke(input=replay_input)

                # Parse and validate response
                try:
                    result = json.loads(result_str)
                except json.JSONDecodeError as e:
                    raise ValueError(f"Invalid JSON response: {e}") from e

                # Extract the image URL
                if not isinstance(result, dict):
                    raise ValueError(f"Expected dict response, got {type(result).__name__}")

                image_url = result.get("imageUrl")
                if not image_url:
                    raise ValueError("Missing 'imageUrl' in response")

                image_urls.append(image_url)
                processed_count += 1
                logger.info(f"Successfully retrieved URL: {image_url}")

            except Exception as e:
                error_msg = f"Error processing stream {pair.stream_id} at {pair.start_time}: {e!s}"
                logger.error(error_msg)
                errors.append({"stream_id": pair.stream_id, "start_time": pair.start_time, "error": str(e)})

        # Log final results
        logger.info(
            f"Batch processing complete. Successfully processed {processed_count}/{len(input_data.stream_time_pairs)} pairs"
        )
        if errors:
            logger.warning(f"Encountered {len(errors)} errors during processing")

        return VSTBatchReplayPicturesOutput(image_urls=image_urls, processed_count=processed_count, errors=errors)

    yield FunctionInfo.create(
        single_fn=_vst_batch_replay_pictures,
        description=_vst_batch_replay_pictures.__doc__,
        input_schema=VSTBatchReplayPicturesInput,
        single_output_schema=VSTBatchReplayPicturesOutput,
    )
